-- Fix seeded dummy advisors: set status to 'offline' (they were incorrectly set to 'online')
-- Only affects the 20 seeded advisor accounts; real advisors who logged in are unaffected.

UPDATE public.advisor_details
SET status = 'offline'
WHERE id IN (
  '45dd82c1-c457-480b-af66-4c07bd0a9d01',
  'd0000002-0000-4000-a000-000000000002',
  'd0000003-0000-4000-a000-000000000003',
